def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    weak_opp_count = 0
    rich_opp_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_opp_count += 1
            if opp.get('budget', 0) >= 140:
                rich_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 1.0
    if supply <= 16:
        scarcity = 1.25
    elif supply >= 22:
        scarcity = 0.9

    urgency = 0
    if hp <= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 2:
        urgency = 2
    elif hp <= 6 or no_water >= 1:
        urgency = 1

    if urgency == 3:
        bid = max(0.95 * DAILY_SALARY, highest_prev + 4.0, avg_prev + 8.0)
    elif urgency == 2:
        bid = max(0.72 * DAILY_SALARY, highest_prev + 2.0)
    elif urgency == 1:
        if highest_prev >= 120:
            bid = 0.42 * DAILY_SALARY
        else:
            bid = max(0.5 * DAILY_SALARY, avg_prev * 0.9 + 3.0)
    else:
        if supply <= 16 and rich_opp_count >= 2:
            bid = 0.18 * DAILY_SALARY
        elif highest_prev >= 120:
            bid = 0.28 * DAILY_SALARY
        else:
            bid = max(0.34 * DAILY_SALARY, avg_prev * 0.6)

    if weak_opp_count >= 2 and urgency <= 1:
        bid *= 0.9

    bid *= scarcity

    if day >= 8:
        bid *= 1.08

    reserve_floor = 0.0
    if hp > 4:
        reserve_floor = 20.0
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Estimate opponents' likely pressure from yesterday's bids
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify if a rival is a high spender (likely to win again)
    # Use yesterday's bid as a proxy.
    high_spender = False
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            if float(b) >= DAILY_SALARY * 1.1:
                high_spender = True
                break
        except Exception:
            continue

    # If my hp is low or I already went without water, bid more aggressively.
    if hp <= 2 or no_water_days >= 1:
        target = DAILY_SALARY * (0.85 if not high_spender else 1.05)
    else:
        # Otherwise, bid to beat the likely low bidders without matching Cindy-style spikes.
        if highest_prev_bid >= DAILY_SALARY * 1.0:
            # High pressure day: bid moderately below the leader to avoid burning budget.
            target = min(DAILY_SALARY * 0.95, highest_prev_bid * 0.9)
        else:
            # Low pressure: bid enough to secure water, but keep budget.
            target = max(DAILY_SALARY * 0.45, highest_prev_bid + 2.0)

    # Convert target to a feasible bid range given budget and typical supply scale.
    # Bids are in salary-like units; cap by budget.
    bid = float(min(budget, target))

    # Ensure we can still survive: if budget is tiny, bid what we can.
    if bid < 0.0:
        bid = 0.0

    # Additional heuristic: if today's supply is high, competition is less critical; bid lower.
    if supply >= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        bid *= 0.9

    # Final clamp
    if budget <= 0.0:
        return 0.0
    return float(min(budget, max(0.0, bid)))

